SELECT p.gender, t.eventtype, p.dod, percent_rank() OVER (PARTITION BY p.dod ORDER BY i.los) AS percentile_rank, percent_rank() OVER (PARTITION BY p.dod, i.discharge_location ORDER BY i.los) AS percentile_rank_discharge_location, percent_rank() OVER (PARTITION BY p.dod, i.discharge_location, i.deathtime ORDER BY i.los) AS percentile_rank_death FROM patients p JOIN transfers t ON p.subject_id = t.subject_id JOIN icustays i ON t.hadm_id = i.subject_id WHERE p.gender = 'M' AND p.anchor_year = 1948 AND p.anchor_year_group BETWEEN 43 AND 53 AND t.eventtype = 'transfer' AND i.discharge_location IN ('home', 'facility', 'in-hospital death') AND i.deathtime IS NULL;